# file: tests/test_unbidden_robustness.py
import datetime

import pytest
from hypothesis import assume, given, settings
import hypothesis.strategies as st

from migrationservice.compose import even
from migrationservice.models import encrypt_value
from migrationservice.models import decrypt_value
from migrationservice.providers.kaltura import sanitize_username
from migrationservice.providers.panopto import system_role_name
from migrationservice.scheduling import scheduled_at_text
from migrationservice.scheduling import parse_scheduled_at
from migrationservice.scheduling import parse_clock


@settings(max_examples=300, deadline=None)
@given(value=st.integers())
def test_even_never_crashes(value):
    even(value)


@settings(max_examples=300, deadline=None)
@given(value=st.text())
def test_encrypt_value_round_trips(value):
    assume(decrypt_value(value) == value)
    enc = encrypt_value(value)
    dec = decrypt_value(enc)
    assert dec == value


@settings(max_examples=300, deadline=None)
@given(value=st.text())
def test_decrypt_value_never_crashes(value):
    decrypt_value(value)


@settings(max_examples=300, deadline=None)
@given(value=st.text())
def test_sanitize_username_never_crashes(value):
    sanitize_username(value)


@settings(max_examples=300, deadline=None)
@given(value=st.one_of(st.integers(), st.text()))
def test_system_role_name_never_crashes(value):
    system_role_name(value)


@settings(max_examples=300, deadline=None)
@given(value=st.datetimes().map(lambda dt: dt.replace(second=0, microsecond=0)))
def test_scheduled_at_text_round_trips(value):
    text = scheduled_at_text(value)
    result = parse_scheduled_at(text)
    assert result is not None


@settings(max_examples=300, deadline=None)
@given(value=st.text())
def test_parse_scheduled_at_never_crashes(value):
    parse_scheduled_at(value)


@settings(max_examples=300, deadline=None)
@given(value=st.text())
def test_parse_clock_never_crashes(value):
    parse_clock(value)
